/** Reverse lookup: name (lowercase) → ticker. */
export const GPW_NAME_TO_TICKER: Record<string, string> = (() => {
  const out: Record<string, string> = {};
  for (const [ticker, entry] of Object.entries(GPW_SECTOR_MAP)) {
    out[entry.name.toLowerCase()] = ticker;
  }
  return out;
})();
